<section class="container page-section"><?php $this->load->view('commerce/environment'); ?><h1 class="h2">Pesanan & rekonsiliasi</h1><p>Lingkungan <?php echo $environment_label; ?>. Pemeriksaan mengambil status dari Midtrans menggunakan versi konfigurasi saat order dibuat. Refund/sengketa masuk antrean pemeriksaan, tidak mengedit ledger atau menghapus anak.</p>
<form method="get" class="feature-card mb-4"><input type="hidden" name="environment" value="<?php echo $environment; ?>"><label class="form-label" for="status">Status</label><select class="form-select mb-3" id="status" name="status"><?php foreach (array('' => 'Semua','created' => 'Belum terkonfirmasi','pending' => 'Menunggu','paid' => 'Berhasil','expired' => 'Kedaluwarsa','failed' => 'Gagal','cancelled' => 'Batal','review' => 'Perlu rekonsiliasi') as $k => $label): ?><option value="<?php echo $k; ?>"<?php echo $status === $k ? ' selected' : ''; ?>><?php echo $label; ?></option><?php endforeach; ?></select><button class="btn btn-primary">Terapkan</button></form>
<div class="row g-3 mb-4"><?php foreach ($orders as $o): ?><div class="col-md-6"><article class="feature-card"><h2 class="h5"><a href="<?php echo site_url('akun/pesanan/'.(int) $o['id']); ?>">Pesanan #<?php echo (int) $o['id']; ?></a></h2><p>Rp<?php echo number_format((int) $o['amount_idr'], 0, ',', '.'); ?> · <?php echo html_escape($o['status']); ?><?php echo $o['review_required'] ? ' · Perlu rekonsiliasi' : ''; ?></p><p class="mb-0">Akun #<?php echo (int) $o['user_id']; ?> · <?php echo html_escape(study_format_datetime($o['created_at'])); ?></p></article></div><?php endforeach; ?><?php if ( ! $orders): ?><p>Tidak ada pesanan sesuai filter.</p><?php endif; ?></div>
<nav aria-label="Halaman pesanan"><?php if ($page > 1): ?><a href="<?php echo site_url('kelola/pesanan?environment='.$environment.'&halaman='.($page - 1).'&status='.rawurlencode($status)); ?>">Sebelumnya</a><?php endif; ?> · Halaman <?php echo (int) $page; ?> <?php if (count($orders) === 20): ?><a href="<?php echo site_url('kelola/pesanan?environment='.$environment.'&halaman='.($page + 1).'&status='.rawurlencode($status)); ?>">Berikutnya</a><?php endif; ?></nav></section>
